type RootValue struct {
	Deleted      basetypes.BoolValue   `tfsdk:"deleted"`
	FullPath     basetypes.StringValue `tfsdk:"full_path"`
	RepositoryId basetypes.StringValue `tfsdk:"repository_id"`
	Visible      basetypes.BoolValue   `tfsdk:"visible"`
	state        attr.ValueState
}

func (v RootValue) ToTerraformValue(ctx context.Context) (tftypes.Value, error) {
	attrTypes := make(map[string]tftypes.Type, 4)

	var val tftypes.Value
	var err error

	attrTypes["deleted"] = basetypes.BoolType{}.TerraformType(ctx)
	attrTypes["full_path"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["repository_id"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["visible"] = basetypes.BoolType{}.TerraformType(ctx)

	objectType := tftypes.Object{AttributeTypes: attrTypes}

	switch v.state {
	case attr.ValueStateKnown:
		vals := make(map[string]tftypes.Value, 4)

		val, err = v.Deleted.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["deleted"] = val

		val, err = v.FullPath.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["full_path"] = val

		val, err = v.RepositoryId.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["repository_id"] = val

		val, err = v.Visible.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["visible"] = val

		if err := tftypes.ValidateValue(objectType, vals); err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		return tftypes.NewValue(objectType, vals), nil
	case attr.ValueStateNull:
		return tftypes.NewValue(objectType, nil), nil
	case attr.ValueStateUnknown:
		return tftypes.NewValue(objectType, tftypes.UnknownValue), nil
	default:
		panic(fmt.Sprintf("unhandled Object state in ToTerraformValue: %s", v.state))
	}
}

func (v RootValue) IsNull() bool {
	return v.state == attr.ValueStateNull
}

func (v RootValue) IsUnknown() bool {
	return v.state == attr.ValueStateUnknown
}

func (v RootValue) String() string {
	return "RootValue"
}

func (v RootValue) ToObjectValue(ctx context.Context) (basetypes.ObjectValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	attributeTypes := map[string]attr.Type{
		"deleted":       basetypes.BoolType{},
		"full_path":     basetypes.StringType{},
		"repository_id": basetypes.StringType{},
		"visible":       basetypes.BoolType{},
	}

	if v.IsNull() {
		return types.ObjectNull(attributeTypes), diags
	}

	if v.IsUnknown() {
		return types.ObjectUnknown(attributeTypes), diags
	}

	objVal, diags := types.ObjectValue(
		attributeTypes,
		map[string]attr.Value{
			"deleted":       v.Deleted,
			"full_path":     v.FullPath,
			"repository_id": v.RepositoryId,
			"visible":       v.Visible,
		})

	return objVal, diags
}

func (v RootValue) Equal(o attr.Value) bool {
	other, ok := o.(RootValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.Deleted.Equal(other.Deleted) {
		return false
	}

	if !v.FullPath.Equal(other.FullPath) {
		return false
	}

	if !v.RepositoryId.Equal(other.RepositoryId) {
		return false
	}

	if !v.Visible.Equal(other.Visible) {
		return false
	}

	return true
}

